import{_ as s,C as t,o as l,a as n,D as a,G as d}from"./chunks/framework.DrK6JUm_.js";const m=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),o={name:"guide/index.md"};function r(c,e,h,p,u,g){const i=t("CopyPrompt");return l(),n("div",null,[e[0]||(e[0]=a('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /guide.md for this page in Markdown format</div><h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h1><p>Vite+ is the unified toolchain and entry point for web development. It manages your runtime, package manager, and frontend toolchain in one place by combining <a href="https://vite.dev/" target="_blank" rel="noreferrer">Vite</a>, <a href="https://vitest.dev/" target="_blank" rel="noreferrer">Vitest</a>, <a href="https://oxc.rs/docs/guide/usage/linter.html" target="_blank" rel="noreferrer">Oxlint</a>, <a href="https://oxc.rs/docs/guide/usage/formatter.html" target="_blank" rel="noreferrer">Oxfmt</a>, <a href="https://rolldown.rs/" target="_blank" rel="noreferrer">Rolldown</a>, <a href="https://tsdown.dev/" target="_blank" rel="noreferrer">tsdown</a>, and <a href="https://github.com/voidzero-dev/vite-task" target="_blank" rel="noreferrer">Vite Task</a>.</p><p>Vite+ ships in two parts: <code>vp</code>, the global command-line tool, and <code>vite-plus</code>, the local package installed in each project. If you already have a Vite project, use <a href="/guide/migrate"><code>vp migrate</code></a> to migrate it to Vite+, or paste our <a href="/guide/migrate#migration-prompt">migration prompt</a> into your coding agent.</p><p>Building with an AI assistant? Copy a ready-made setup prompt:</p>',5)),d(i),e[1]||(e[1]=a(`<h2 id="install-vp" tabindex="-1">Install <code>vp</code> <a class="header-anchor" href="#install-vp" aria-label="Permalink to “Install vp”">​</a></h2><h3 id="macos-linux" tabindex="-1">macOS / Linux <a class="header-anchor" href="#macos-linux" aria-label="Permalink to “macOS / Linux”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://vite.plus</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h3><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vite.plus</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>Alternatively, download and run <a href="https://setup.viteplus.dev" target="_blank" rel="noreferrer"><code>vp-setup.exe</code></a>.</p><div class="tip custom-block"><p class="custom-block-title">SmartScreen warning</p><p>The <code>vp-setup.exe</code> is not yet code-signed. Your browser may show a warning when downloading. Click <strong>&quot;...&quot;</strong> → <strong>&quot;Keep&quot;</strong> → <strong>&quot;Keep anyway&quot;</strong> to proceed. If Windows Defender SmartScreen blocks the file when you run it, click <strong>&quot;More info&quot;</strong> → <strong>&quot;Run anyway&quot;</strong>.</p></div><p>After installation, open a new shell and run:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Vite+ will manage your global Node.js runtime and package manager. If you&#39;d like to opt out of this behavior, run <code>vp env off</code>. If you realize Vite+ is not for you, type <code>vp implode</code>, but please <a href="https://discord.gg/cAnsqHh5PX" target="_blank" rel="noreferrer">share your feedback with us</a>.</p></div><details class="details custom-block"><summary>Using a minor platform (CPU architecture, OS) ?</summary><p>Prebuilt binaries are distributed for the following platforms (grouped by <a href="https://github.com/nodejs/node/blob/v24.x/BUILDING.md#platform-list" target="_blank" rel="noreferrer">Node.js v24 platform support tier</a>):</p><ul><li>Tier 1 <ul><li>Linux x64 glibc (<code>x86_64-unknown-linux-gnu</code>)</li><li>Linux arm64 glibc (<code>aarch64-unknown-linux-gnu</code>)</li><li>Windows x64 (<code>x86_64-pc-windows-msvc</code>)</li><li>macOS x64 (<code>x86_64-apple-darwin</code>)</li><li>macOS arm64 (<code>aarch64-apple-darwin</code>)</li></ul></li><li>Tier 2 <ul><li>Windows arm64 (<code>aarch64-pc-windows-msvc</code>)</li></ul></li><li>Experimental <ul><li>Linux x64 musl (<code>x86_64-unknown-linux-musl</code>)</li></ul></li><li>Other <ul><li>Linux arm64 musl (<code>aarch64-unknown-linux-musl</code>)</li></ul></li></ul><p>If a prebuilt binary is not available for your platform, installation will fail with an error.</p><p>On Alpine Linux (musl), you need to install <code>libstdc++</code> before using Vite+:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libstdc++</span></span></code></pre></div><p>This is required because the managed <a href="https://unofficial-builds.nodejs.org/" target="_blank" rel="noreferrer">unofficial-builds</a> Node.js runtime depends on the GNU C++ standard library.</p></details><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start”">​</a></h2><p>Create a project, install dependencies, and use the default commands:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Create a new project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Install dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Start the dev server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Format, lint, type-check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Run JavaScript tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Build for production</span></span></code></pre></div><p>You can also just run <code>vp</code> on its own and use the interactive command line.</p><h2 id="core-commands" tabindex="-1">Core Commands <a class="header-anchor" href="#core-commands" aria-label="Permalink to “Core Commands”">​</a></h2><p>Vite+ can handle the entire local frontend development cycle from starting a project, developing it, checking &amp; testing, and building it for production.</p><h3 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to “Start”">​</a></h3><ul><li><a href="/guide/create"><code>vp create</code></a> creates new apps, packages, and monorepos.</li><li><a href="/guide/migrate"><code>vp migrate</code></a> moves existing projects onto Vite+.</li><li><a href="/guide/commit-hooks"><code>vp config</code></a> configures commit hooks and agent integration.</li><li><a href="/guide/commit-hooks"><code>vp staged</code></a> runs checks on staged files.</li><li><a href="/guide/install"><code>vp install</code></a> installs dependencies with the right package manager.</li><li><a href="/guide/env"><code>vp env</code></a> manages Node.js versions.</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li><a href="/guide/dev"><code>vp dev</code></a> starts the dev server powered by Vite.</li><li><a href="/guide/check"><code>vp check</code></a> runs format, lint, and type checks together.</li><li><a href="/guide/lint"><code>vp lint</code></a>, <a href="/guide/fmt"><code>vp fmt</code></a>, and <a href="/guide/test"><code>vp test</code></a> let you run those tools directly.</li></ul><h3 id="execute" tabindex="-1">Execute <a class="header-anchor" href="#execute" aria-label="Permalink to “Execute”">​</a></h3><ul><li><a href="/guide/run"><code>vp run</code></a> runs tasks across workspaces with caching.</li><li><a href="/guide/vpx"><code>vp exec</code></a> runs local project binaries.</li><li><a href="/guide/env"><code>vp node</code></a> runs Node.js scripts with the resolved Vite+ environment.</li><li><a href="/guide/vpx"><code>vp dlx</code></a> downloads and runs package binaries without adding them as dependencies.</li><li><a href="/guide/cache"><code>vp cache clean</code></a> clears task cache entries.</li><li><a href="/guide/vpx"><code>vpx</code></a> downloads and runs binaries globally.</li></ul><h3 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to “Build”">​</a></h3><ul><li><a href="/guide/build"><code>vp build</code></a> builds apps.</li><li><a href="/guide/pack"><code>vp pack</code></a> builds libraries or standalone artifacts.</li><li><a href="/guide/build"><code>vp preview</code></a> previews the production build locally.</li></ul><h3 id="manage-dependencies" tabindex="-1">Manage Dependencies <a class="header-anchor" href="#manage-dependencies" aria-label="Permalink to “Manage Dependencies”">​</a></h3><ul><li><a href="/guide/install"><code>vp add</code></a>, <a href="/guide/install"><code>vp remove</code></a>, <a href="/guide/install"><code>vp update</code></a>, <a href="/guide/install"><code>vp dedupe</code></a>, <a href="/guide/install"><code>vp outdated</code></a>, <a href="/guide/install"><code>vp list</code></a>, <a href="/guide/install"><code>vp why</code></a>, and <a href="/guide/install"><code>vp info</code></a> wrap package-manager workflows.</li><li><a href="/guide/install"><code>vp link</code></a>, <a href="/guide/install"><code>vp unlink</code></a>, and <a href="/guide/install"><code>vp rebuild</code></a> cover local package links and native module rebuilds.</li><li><a href="/guide/install"><code>vp pm &lt;command&gt;</code></a> calls other package manager commands directly.</li></ul><h3 id="maintain" tabindex="-1">Maintain <a class="header-anchor" href="#maintain" aria-label="Permalink to “Maintain”">​</a></h3><ul><li><a href="/guide/upgrade"><code>vp upgrade</code></a> updates the <code>vp</code> installation itself.</li><li><a href="/guide/implode"><code>vp implode</code></a> removes <code>vp</code> and related Vite+ data from your machine.</li></ul><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Vite+ ships with many predefined commands such as <code>vp build</code>, <code>vp test</code>, and <code>vp dev</code>. These commands are built-in and cannot be changed. If you want to run a command from your <code>package.json</code> scripts, use <code>vp run &lt;command&gt;</code> or <code>vpr &lt;command&gt;</code>.</p><p><a href="/guide/run">Learn more about <code>vp run</code>.</a></p></div>`,30))])}const f=s(o,[["render",r]]);export{m as __pageData,f as default};
